#include "ram_bridge.h"
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#define A(x) (TF_RAM_BASE+UINT32_C(x))
static ta_model m;static rc_adapter adapter;
static uint8_t runtime[76800],boot[12288],uid[14],known[14],flash[1024];
static unsigned groups,checks,failures,patterns,programs;static uint32_t raw_clock;static int pattern_return;
#define CHECK(x) do{checks++;if(!(x)){failures++;printf("FAIL line=%d %s\n",__LINE__,#x);}}while(0)
static void group(const char *s){groups++;printf("GROUP %s\n",s);}
static void put(uint32_t a,uint32_t v,unsigned n){unsigned i;for(i=0;i<n;i++){m.memory.ram[a-TF_RAM_BASE+i]=(uint8_t)(v>>(8*i));m.memory.known[a-TF_RAM_BASE+i]=255;}}
static uint32_t get(uint32_t a,unsigned n){unsigned i;uint32_t v=0;for(i=0;i<n;i++)v|=(uint32_t)m.memory.ram[a-TF_RAM_BASE+i]<<(8*i);return v;}
static int connection(void *p,uint16_t h,uint32_t q){(void)p;(void)q;CHECK(h==7);return 1;}
static int clock_value(void *p,uint32_t token,uint32_t *v){(void)p;CHECK(token==0x18f1a||token==0x33cc);*v=raw_clock;return 1;}
static int status_value(void *p,rc_adapter *a,unsigned code,uint32_t detail){(void)p;(void)a;(void)code;(void)detail;return 1;}
static void read_value(void *p,uint32_t a,uint8_t *d,uint8_t *k,size_t n){size_t i;(void)p;memset(k,255,n);for(i=0;i<n;i++){uint32_t x=a+(uint32_t)i;d[i]=0;if(x>=0x1ffff7ec&&x<0x1ffff7f4)d[i]=uid[x-0x1ffff7ec];else if(x>=0x1ffff7e8&&x<0x1ffff7ee)d[i]=uid[8+x-0x1ffff7e8];else if(x>=0x08008000&&x<0x08008400)d[i]=flash[x-0x08008000];else if(x==0x08077b01)d[i]=2;else if(x==0x08077b04)d[i]=2;}}
static tc_flow program_value(void *p,uint32_t a,const uint8_t *d,const uint8_t *k){unsigned i;(void)p;programs++;CHECK(a>=0x08008000&&a<=0x08008300);for(i=0;i<256;i++){CHECK(k[i]==255);flash[a-0x08008000+i]=d[i];}return TC_RETURNED;}
static gb_flow helper(void *p,gb_model *g,const gb_request *r,gb_scalar *v){(void)p;(void)g;if(r->kind==GB_NATIVE_HELPER&&r->target==0x1d54){patterns++;CHECK(r->argument_count==1&&r->arguments[0]==3&&r->known[0]==UINT32_MAX);if(!pattern_return)return GB_HALT;v->value=0;v->known=UINT32_MAX;return GB_RETURNED;}return GB_HALT;}
static void fresh(tc_image image){tc_backend io;tf_backend features;ta_link_backend link;rc_hooks hooks;gb_backend general;uint32_t result=9;uint8_t task=255;memset(&io,0,sizeof(io));memset(&features,0,sizeof(features));memset(&hooks,0,sizeof(hooks));memset(&general,0,sizeof(general));io.read=read_value;io.program256=program_value;features.memory_contracts=1;link.context=NULL;link.connection_status=connection;ta_init(&m,image,runtime,sizeof(runtime),&io,&features,&link);if(image==TC_BOOT)CHECK(ta_boot_cold_start(&m,boot,sizeof(boot))==BR_RETURNED);
    /* Explicit synthetic ROM .data/config fixture; never evidence of physical RAM. */
    memset(m.memory.ram,0,0x4000);memset(m.memory.known,255,0x4000);
    hooks.clock=clock_value;hooks.status=status_value;raw_clock=0;
    CHECK(rc_attach(&adapter,&m.memory,RC_WCH_64BE955_V130,&hooks)==1);CHECK(rc_prepare(&adapter,image==TC_RUNTIME?A(0x418c):A(0x40a4),image==TC_RUNTIME?0x7000:0x5000,image==TC_RUNTIME?14:13)==1);
    CHECK(rc_task_register(&adapter,image==TC_RUNTIME?0x8ff8:0x1a64,&task)==1&&task==3);put(image==TC_RUNTIME?A(0x40ae):A(0x408a),task,1);
    CHECK(rc_task_register(&adapter,image==TC_RUNTIME?0x13902:0x24a8,&task)==1&&task==4);if(image==TC_BOOT)put(A(0x408d),task,1);
    CHECK(rc_clock_init(&adapter,image==TC_RUNTIME?0x18f1a:0x33cc,UINT32_MAX,16000,1000,1,&result)==1&&result==0);CHECK(ta_attach_candidate(&m,&adapter)==1);
    put(image==TC_RUNTIME?A(0x409e):A(0x407e),7,2);put(image==TC_RUNTIME?A(0x409c):A(0x407c),4,1);
    if(image==TC_RUNTIME)put(A(0x40a2),0xfffe,2);
    general.invoke=helper;ta_set_general_backend(&m,&general);tc_identity(&m.ota,uid,known);m.ota.uart_ready=TC_YES;m.ota.alloc_ok=TC_YES;patterns=programs=0;pattern_return=1;memset(flash,0,sizeof(flash));
}
static size_t frame(uint8_t *w,uint8_t c,const uint8_t *d,size_t n){size_t i;uint8_t sum=(uint8_t)(c+(n>>8)+(n&255));w[0]=0x55;w[1]=0x7f;w[2]=c;w[3]=(uint8_t)(n>>8);w[4]=(uint8_t)n;for(i=0;i<n;i++){w[5+i]=d[i];sum=(uint8_t)(sum+d[i]);}w[5+n]=sum;return n+6;}
static void reply_heap(void){uint8_t d[4]={9,8,7,6},k[4]={255,255,255,255};gb_reply_request r;uint32_t before,after,ops;group("GATT reply actually allocates/copies/frees candidate message in shared SRAM");fresh(TC_RUNTIME);CHECK(rc_heap_free_sum(&adapter,&before)==1);ops=adapter.operations;memset(&r,0,sizeof(r));r.handle=7;r.command=0xad;r.data=d;r.known=k;r.length=4;r.wrapper_va=0x13960;CHECK(m.general.backend.reply(m.general.backend.context,&m.general,&r)==GB_RETURNED);CHECK(adapter.operations>=ops+2);CHECK(get(A(0x43bc),1)==9&&get(A(0x43bf),1)==6);CHECK(get(A(0xb197),1)==9&&get(A(0xb19a),1)==6);CHECK(get(A(0xb18e),2)==10);CHECK(rc_heap_free_sum(&adapter,&after)==1&&before==after);CHECK(m.replies_committed==1);}
static void reply_unknown(void){uint8_t d=8,k=255;gb_reply_request r;group("unclosed candidate allocator preserves prefix and stops before native builder");fresh(TC_RUNTIME);memset(&r,0,sizeof(r));r.handle=7;r.command=0xad;r.data=&d;r.known=&k;r.length=1;r.wrapper_va=0x13960;m.memory.known[0x3044]=0;CHECK(m.general.backend.reply(m.general.backend.context,&m.general,&r)==GB_HALT);CHECK(m.replies_committed==0);CHECK(get(A(0xb18e),2)==0);CHECK(m.halted==1);}
static void replacement_free(void){uint32_t p=0;group("matched callback argument uses actual candidate message deallocation before overwrite");fresh(TC_RUNTIME);CHECK(rc_msg_allocate(&adapter,4,&p)==1&&p!=0);CHECK(tf_schedule(&m.memory,0x95ec,0,100,p)==0);CHECK(tf_schedule(&m.memory,0x95ec,0,200,0)==0);CHECK(get(p-10,2)==0);CHECK(get(TF_REGISTRY+8,4)==0);fresh(TC_RUNTIME);CHECK(rc_msg_allocate(&adapter,4,&p)==1&&p!=0);CHECK(tf_schedule(&m.memory,0x95ec,0,100,p)==0);m.memory.known[p-TF_RAM_BASE-2]=0;CHECK(tf_schedule(&m.memory,0x95ec,0,200,0)==TF_UNKNOWN);CHECK(get(TF_REGISTRY+8,4)==p);}
static void shared_timer(void){uint8_t w[16];size_t n;uint32_t node=0;uint16_t events=0;group("OTA schedule becomes candidate timer and explicit event delivery in same SRAM");fresh(TC_RUNTIME);put(A(0x40b1),1,1);n=frame(w,'E',NULL,0);CHECK(ta_receive(&m,7,w,n,1)==n);CHECK(get(TF_REGISTRY+4,4)==0x8e12);CHECK(get(TF_REGISTRY+16,4)==0x99c6);CHECK(rc_timer_find(&adapter,3,1,&node)==1&&node!=0);CHECK(get(node+8,4)==3200);raw_clock=3200;CHECK(rc_timer_pump(&adapter)==1);CHECK(rc_take_event(&adapter,3,&events)==1&&events==1);CHECK(ta_dispatch_runtime(&m,events)==events);CHECK(m.halted==1&&m.native_callbacks.unknown_va==0x8e2a);CHECK(get(TF_REGISTRY+4,4)==0);CHECK(get(TF_REGISTRY+16,4)==0x99c6);}
static void uart_flow(void){uint8_t w[1040],d[1026],key;size_t n;unsigned i;uint32_t node=0;group("UART I/S/W/E import and export original session/key/plaintext and startup timer");fresh(TC_BOOT);put(A(0x408b),0x77,1);n=frame(w,'I',NULL,0);CHECK(ta_receive_uart(&m,w,n,1)==n);CHECK(patterns==1);CHECK(get(A(0x408c),1)==1);CHECK(get(A(0x999c),1)==1);CHECK(get(A(0x408b),1)==0x77);CHECK(get(A(0x999d),1)==0);key=(uint8_t)get(A(0x999e),1);n=frame(w,'S',&key,1);CHECK(ta_receive_uart(&m,w,n,2)==n);CHECK(get(A(0x999c),1)==2);CHECK(get(A(0x999f),1)==0);key=(uint8_t)get(A(0x999e),1);d[0]=d[1]=0;for(i=0;i<1024;i++)d[i+2]=(uint8_t)((i&255)^(uint8_t)(key+i));n=frame(w,'W',d,1026);CHECK(ta_receive_uart(&m,w,n,3)==n);CHECK(programs==4);CHECK(get(A(0x9594),1)==0&&get(A(0x9595),1)==1);CHECK(get(A(0x999f),1)==0);CHECK(get(A(0x999c),1)==2);for(i=0;i<1024;i++)CHECK(flash[i]==(uint8_t)i);key=(uint8_t)(get(A(0x999e),1)^get(A(0x999f),1));n=frame(w,'E',&key,1);CHECK(ta_receive_uart(&m,w,n,4)==n);CHECK(get(A(0x999c),1)==3);CHECK(rc_timer_find(&adapter,4,2,&node)==1&&node!=0);CHECK(get(node+8,4)==480);CHECK(get(BR_REGISTRY+4,4)==0);CHECK(m.replies_committed==0);}
static void uart_boundaries(void){uint8_t w[16],b=0x55;size_t n;uint32_t p=0;group("UART startup boundary, no-byte timeout, distinct registry and resume limits");fresh(TC_BOOT);pattern_return=0;n=frame(w,'I',NULL,0);CHECK(ta_receive_uart(&m,w,n,1)==n-1);CHECK(m.halted==1);CHECK(get(A(0x408c),1)==1);CHECK(get(A(0x999c),1)==0);CHECK(get(A(0x999d),1)==6);fresh(TC_BOOT);CHECK(br_schedule(&m.boot,0x192c,0,100,0)==0);p=get(BR_REGISTRY+4,4);CHECK(br_stop_startup(&m.boot)!=TF_UNKNOWN);CHECK(get(BR_REGISTRY+4,4)==p);put(A(0x999c),2,1);put(A(0x999e),77,1);CHECK(ta_receive_uart(&m,NULL,0,9000)==0);CHECK(get(A(0x999c),1)==2&&get(A(0x4090),4)==0);CHECK(ta_receive_uart(&m,&b,1,9000)==1);CHECK(get(A(0x999c),1)==0&&get(A(0x999e),1)==0);CHECK(get(A(0x999d),1)==1);CHECK(get(A(0x4090),4)==9000);}
static void call_boundaries(void){uint8_t w[16];size_t n;group("unknown ROM call stops command sequence before later schedule/reply/helper");fresh(TC_RUNTIME);put(A(0x40b1),1,1);adapter.hooks.clock=NULL;n=frame(w,'E',NULL,0);CHECK(ta_receive(&m,7,w,n,1)==n-1);CHECK(m.halted==1);CHECK(get(TF_REGISTRY+4,4)==0x8e12);CHECK(get(TF_REGISTRY+16,4)==0);CHECK(get(A(0x40a4),1)==6);CHECK(m.replies_committed==0);fresh(TC_BOOT);m.memory.known[0x3098]=0;n=frame(w,'I',NULL,0);CHECK(ta_receive_uart(&m,w,n,1)==n-1);CHECK(get(A(0x408c),1)==1);CHECK(get(A(0x999c),1)==0);CHECK(patterns==0);CHECK(m.ota.command_count==0);}
static void general_uid(void){uint8_t w[32];size_t n;group("general A5 native auth and two UID OUT-copy calls couple to candidate timers/reply");fresh(TC_RUNTIME);put(A(0xc792),7,2);put(A(0xc794),1,1);put(A(0x40af),1,1);m.ota.general_auth=TC_NO;n=frame(w,0xa5,uid,14);CHECK(ta_receive(&m,7,w,n,1)==n);CHECK(m.halted==0);CHECK(get(TF_REGISTRY+4,4)==0x8e12);CHECK(get(TF_REGISTRY+16,4)==0x99c6);CHECK(m.ota.reply_command==0xa5&&m.ota.reply_data[0]==1);CHECK(m.replies_committed==1);fresh(TC_RUNTIME);put(A(0xc792),7,2);put(A(0xc794),1,1);put(A(0x40af),1,1);m.external.read=NULL;CHECK(ta_receive(&m,7,w,n,1)==n-1);CHECK(m.halted==1);CHECK(m.general.boundary_va==0x92b4);CHECK(get(TF_REGISTRY+4,4)==0);CHECK(get(A(0x40a4),1)==6);}
int main(int argc,char **argv){FILE *f;unsigned i;if(argc!=3)return 2;f=fopen(argv[1],"rb");if(!f||fread(runtime,1,sizeof(runtime),f)!=sizeof(runtime)){if(f)fclose(f);return 2;}fclose(f);f=fopen(argv[2],"rb");if(!f||fread(boot,1,sizeof(boot),f)!=sizeof(boot)){if(f)fclose(f);return 2;}fclose(f);for(i=0;i<14;i++){uid[i]=(uint8_t)(17+i);known[i]=255;}uid[12]=uid[0];uid[13]=uid[1];reply_heap();reply_unknown();replacement_free();shared_timer();uart_flow();uart_boundaries();call_boundaries();general_uid();printf("COUPLED_RESULT groups=%u checks=%u failures=%u original_executed=no hardware=no\n",groups,checks,failures);return failures?1:0;}
